export function findCatalogRules({ term = '', property = '', intent = '' } = {}){
  const t = String(term || '').toLowerCase();
  const p = String(property || '').toLowerCase();
  const i = String(intent || '').toLowerCase();
  return PANEL_LOCATOR_RULE_CATALOG.filter((rule) => (!t || rule.term.includes(t)) && (!p || rule.property.includes(p)) && (!i || rule.intent.includes(i))).slice(0, 120);
}

export function summarizeRuleCatalog(){
  const byIntent = new Map();
  for(const rule of PANEL_LOCATOR_RULE_CATALOG) byIntent.set(rule.intent, (byIntent.get(rule.intent) || 0) + 1);
  return { total: PANEL_LOCATOR_RULE_CATALOG.length, byIntent: Object.fromEntries([...byIntent.entries()].sort()) };
}
